endpoint.response:
Envelope `{ success: true, message, data }`. Importi = stringhe decimali con 2 cifre ("1234.50", "-12.00"),
calcolati in centesimi interi. `today` = data del server.
data: {
  today: "YYYY-MM-DD",
  company_id: number|null,
  liquidity: {
    total: string,
    by_type: { bank_account: string, card: string, cash: string },
    accounts: [ { id: number, name: string, type: "bank_account"|"card"|"cash",
                  company: { id: number, name: string }|null, balance: string } ]
  },
  receivable: {
    open_total: string,          // residuo > 0 delle rate attive (fatture + proforma)
    not_due_total: string,       // open_total - overdue_total
    overdue_total: string,       // scadenza < oggi
    overdue: { overdue_1_30: string, overdue_31_60: string, overdue_61_90: string, overdue_over_90: string }
  },
  payable: { stessa shape di receivable, sulle rate passive },
  net_position: string,          // liquidity.total + receivable.open_total - payable.open_total
  forecast: [                    // sempre 3 righe, days 30, 60, 90, in quest'ordine, cumulative da oggi
    { days: 30|60|90, until: "YYYY-MM-DD" (oggi + days),
      receivable: string,        // residuo rate attive con oggi <= scadenza <= until
      payable: string,           // idem rate passive
      expected_balance: string } // liquidity.total + receivable - payable
  ],
  to_verify: {
    unassigned: { count: number, collections: string, payments: string },  // da unassigned(), somme per source
    adjustments: { month: "YYYY-MM", count: number, inflow: string, outflow: string }  // type=adjustment nel mese corrente
  }
}
